    blank: "避けます", wrong: ["預けます", "貯めます", "迎えます"], check: { q: "どうして 早めに 出かけますか。", choices: ["込んで いる 時間を 避ける ため", "朝ごはんを 食べる ため", "雨だから", "約束が あるから"] },
