    mean: { en: "to admit, to recognize", vi: "thừa nhận, công nhận", id: "mengakui", tl: "aminin, kilalanin" },
    ex: [{ ja: "かれは 自分の まちがいを 認めて、あやまりました。", en: "He admitted his mistake and apologized.", vi: "Anh ấy thừa nhận lỗi của mình và xin lỗi.", id: "Dia mengakui kesalahannya dan meminta maaf.", tl: "Inamin niya ang pagkakamali at humingi ng tawad." },
         { ja: "がんばりが 認められて、リーダーに なりました。", en: "My hard work was recognized and I became a leader.", vi: "Sự nỗ lực được công nhận nên tôi trở thành trưởng nhóm.", id: "Usaha saya diakui dan saya menjadi pemimpin.", tl: "Kinilala ang pagsisikap ko kaya naging lider ako." }],
